            //
            aOrbiterE = ((aOrbiterE + aOrbiterG) + 0x5725F4ECF55DD3C2ULL) + aOrbiterUpdateSaltC[((aIndex + 221U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xF733271E5DA98A9EULL;
