            aOrbiterC = (aOrbiterC + aOrbiterA) + 0x4433EB38884B706EULL;
            aOrbiterH = (((aOrbiterH ^ aOrbiterC) ^ 0x5777D7885163206AULL) ^ aOrbiterUpdateSaltE[(((255U - aIndex) + 150U)) & S_SALT1]) ^ aNonceWordK;
