            aIngress = (RotL64(aHeartLaneA[((aIndex + 15676U)) & S_BLOCK1], 23U) ^ RotL64(aWaterLaneC[((aIndex + 15501U)) & S_BLOCK1], 35U));
            aIngress ^= (RotL64(aNonceLane[((aIndex + 12605U)) & S_BLOCK1], 52U) ^ RotL64(aEarthLaneA[((aIndex + 16276U)) & S_BLOCK1], 13U));
            aIngress = TwistMix64::DiffuseA(((aIngress ^ aDomainWordIngress) ^ aNonceWordM));
