            aCross = (RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 15590U)) & S_BLOCK1], 48U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 11498U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aSource[((S_BLOCK1 - aIndex + 11923U)) & S_BLOCK1], 13U) ^ RotL64(aWindLaneD[((aIndex + 10633U)) & S_BLOCK1], 21U));
            aCross = TwistMix64::DiffuseB(((aCross ^ aDomainWordCross) ^ aNonceWordL));
