            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xB82C88904FD147D5ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterE) ^ 0xC5B2FB02E06F86CCULL) ^ aOrbiterUpdateSaltF[(((255U - aIndex) + 209U)) & S_SALT1];
