            aOrbiterB = RotL64((aOrbiterB * 0x94E24DB867A3BEC5ULL), 23U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x1F95BEAA12CEF99EULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0x636B5C577DA96FA5ULL) ^ aNonceWordH;
            aOrbiterA = RotL64((aOrbiterA * 0x4CB1DBAACD6DCFE5ULL), 5U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0xE352721E48EA09DDULL) + aOrbiterUpdateSaltB[((aIndex + 194U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0x8881153DC8DED21AULL) ^ aOrbiterUpdateSaltA[(((255U - aIndex) + 224U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xA7236718A4AD69D1ULL), 51U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0x983CB2FE9C24B576ULL) + aOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0xD9C7BEC887D27C54ULL) ^ aNonceWordI;
            aOrbiterK = RotL64((aOrbiterK * 0x4EE9EC07A542FA9DULL), 37U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x3151BF52DD51E034ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x083F94CC696762EDULL;
