            aOrbiterE = RotL64((aOrbiterE * 0xF55BBC88A4977703ULL), 35U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0xBD1CE9C05A1A3CDAULL) + aTwistOrbiterUpdateSaltE[(((255U - aIndex) + 116U)) & S_SALT1];
