            //
            aOrbiterD = (aWandererB + RotL64(aIngress, 26U)) + 0x2C16E516A12D094EULL;
            aOrbiterF = ((aWandererD + RotL64(aPrevious, 5U)) + RotL64(aCarry, 19U)) + 0x224468CB4FA1B567ULL;
            aOrbiterA = ((aWandererG + RotL64(aCross, 41U)) + 0x987B95F10CBF15F6ULL) + aTwistOrbiterAssignSaltC[((aIndex + 39U)) & S_SALT1];
            aOrbiterG = ((aWandererA + RotL64(aScatter, 57U)) + 0x2D46E0D1118D1B27ULL) + aTwistOrbiterAssignSaltA[((aIndex + 189U)) & S_SALT1];
