            aOrbiterG = (aWandererB + RotL64(aIngress, 57U)) + 0xB49464368085B088ULL;
            aOrbiterB = (aWandererF + RotL64(aCross, 23U)) + 0x5C7C8C1B868676B5ULL;
            aOrbiterK = ((aWandererK + RotL64(aScatter, 18U)) + RotL64(aCarry, 47U)) + 0x253790939879580DULL;
