            aOrbiterA = ((aWandererJ + RotL64(aCross, 53U)) + RotL64(aCarry, 35U)) + 0xCA1D3B1C88E04E1EULL;
            aOrbiterD = (aWandererC + RotL64(aPrevious, 34U)) + 0x9E5DC0D12064CF1DULL;
