            aOrbiterI = RotL64((aOrbiterI * 0xEBE96067DD2C6653ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x515CD12C5A21862AULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x9D167BCD165A09BAULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x67692A74F2B15225ULL), 23U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0xA5A9D8D53719DB81ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0xCF59241E489CDB2DULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 108U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x95754D392771294DULL), 51U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xB08FDDDA1923E31EULL;
