            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0x9B65CF7B7553D222ULL) + aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 67U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xAB397C1D7A58DF0FULL) ^ aTwistOrbiterUpdateSaltE[(((255U - aIndex) + 23U)) & S_SALT1];
