            aOrbiterJ = ((aWandererG + RotL64(aIngress, 27U)) + RotL64(aCarry, 13U)) + 0x5283974ECC6D6A34ULL;
            aOrbiterH = (aWandererJ + RotL64(aCross, 43U)) + 0x22C89996EABA8721ULL;
            aOrbiterA = (((aWandererK + RotL64(aScatter, 3U)) + RotL64(aCarry, 51U)) + 0xED37C464C9F890B4ULL) + aTwistOrbiterAssignSaltD[((aIndex + 16U)) & S_SALT1];
            aOrbiterI = ((aWandererD + RotL64(aPrevious, 35U)) + RotL64(aCarry, 39U)) + 0x268A63B87206A6C3ULL;
            aOrbiterD = (aWandererB + RotL64(aIngress, 13U)) + 0xB7C8D6FEBD5E1351ULL;
