            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x44368EDA20EEA8FDULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0xED4B0587DCD20CE9ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 89U)) & S_SALT1];
