            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x061B5031F613AAB9ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0xECC6CC3C5411A6F4ULL) ^ aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 56U)) & S_SALT1];
