            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xD35E699ADEE338E3ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0x2AC7DEE97E40CED9ULL;
