            aOrbiterF = (aWandererD + RotL64(aScatter, 57U)) + 0x7186ED35B9F252CCULL;
            aOrbiterA = (((aWandererI + RotL64(aCross, 5U)) + RotL64(aCarry, 27U)) + 0xD42827EB904C7248ULL) + aKeyRotateAOrbiterAssignSaltE[(((255U - aIndex) + 35U)) & S_SALT1];
