            aOrbiterI = ((aWandererI + RotL64(aPrevious, 3U)) + RotL64(aCarry, 23U)) + 0xCC4650E1F06284B9ULL;
            aOrbiterJ = ((aWandererC + RotL64(aIngress, 11U)) + 0xEB6C39560BDD1B16ULL) + aKeyRotateBOrbiterAssignSaltD[((aIndex + 124U)) & S_SALT1];
