            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x3C498EE7BC9AAFB9ULL) ^ aKeyRotateBOrbiterUpdateSaltE[(((255U - aIndex) + 117U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xE42044D5DCC3E339ULL), 11U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0x6363DC3F0B8C589EULL) + aKeyRotateBOrbiterUpdateSaltD[(((255U - aIndex) + 47U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0x7D889AA190153BB4ULL;
