            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x66DA619B92EA9F82ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x324C677CFD880B6DULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xDEBE1B3C1DB28EE0ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x3B21F620DC3011F5ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x3435421328369913ULL), 29U);
